const t = $json.token;

// Defeito REAL da API da 3S (medido 21/08/2026): apos periodo ocioso o
// ValidaLogin as vezes devolve HTTP 200 com token de SESSAO VELHO ja vencido —
// hex de 32 chars em vez de JWT. Foi o que derrubou as execucoes agendadas de
// 20 e 21/08 com "Authorization failed" no node seguinte. Aqui vira erro
// claro, no lugar certo.
if (!t || typeof t !== 'string') {
  throw new Error('[3S] Login nao devolveu token. Corpo: ' + JSON.stringify($json).slice(0, 200));
}
if (!t.startsWith('eyJ')) {
  throw new Error('[3S] Login devolveu token invalido (esperado JWT, veio ' + t.length +
    ' chars: "' + t.slice(0, 16) + '..."). Defeito de cache da 3S — o login de ' +
    'aquecimento nao resolveu desta vez. Reexecutar costuma bastar.');
}

// VALIDADE: le o claim "exp" de DENTRO do JWT (epoch em segundos, UTC, sem
// ambiguidade de fuso).
//
// NAO usar o campo "expiration" do corpo da resposta: ele vem em horario LOCAL
// (BRT) e SEM sufixo de fuso, e o new Date() do Node interpreta string ISO sem
// fuso como hora do SERVIDOR. Com o n8n em UTC, um token valido ate 11:03 BRT
// (= 14:03 UTC) era lido como vencido as 11:03 UTC — falso positivo de 3h que
// derrubou o 3S-10 em 21/08/2026. Confirmado antes: o claim exp do JWT marcava
// 14:38 UTC enquanto o corpo dizia 11:38.
//
// Se por algum motivo nao der para decodificar, segue SEM checar validade: o
// risco de barrar token bom e pior que o de deixar passar um vencido, porque
// vencido falha logo adiante com erro claro da propria API.
let expSeg = null;
try {
  const payload = JSON.parse(Buffer.from(t.split('.')[1], 'base64').toString('utf8'));
  if (payload && payload.exp) expSeg = Number(payload.exp);
} catch (e) { /* segue sem checar */ }

if (expSeg && expSeg * 1000 <= Date.now()) {
  throw new Error('[3S] Login devolveu JWT ja vencido (exp=' +
    new Date(expSeg * 1000).toISOString() + ', agora=' + new Date().toISOString() +
    '). Defeito de cache da 3S.');
}

return [{ json: { token: t, expiration: $json.expiration } }];

const { response_corpo, id } = $json;
if (!response_corpo || String(response_corpo).trim() === '') {
  throw new Error('[3S] Resposta VAZIA (HTTP 200 com corpo vazio). Causa mais provavel: ' +
    'token invalido ou ausente no header Authorization — a 3S devolve 200 + corpo vazio ' +
    'nesse caso, em vez de 401. Confira o node de Login e a expressao do header.');
}
const parsed = JSON.parse(response_corpo);

// Equivalente do GUARD_SEM_CONTEUDO para este endpoint: RetornaDados sempre
// devolve o envelope { Dados: {...} }. Ausencia do envelope = resposta
// degenerada (token quebrado), nao "nenhum evento novo" — este ultimo caso
// vem como envelope presente com as listas vazias, e e tratado normalmente.
if (!parsed || (!parsed.Dados && !parsed.dados)) {
  throw new Error('[3S] RetornaDados sem o envelope Dados na resposta. Sintoma classico ' +
    'de token quebrado no header Authorization. Corpo recebido: ' +
    String(response_corpo).slice(0, 200));
}

const dados = parsed.Dados || parsed.dados || {};

// Mapa chave do JSON -> tipo canonico (silver.ref_tipo_evento espelha isto)
const TIPOS = [
  ['AlertaVelocidade',  'ALERTA_VELOCIDADE'],
  ['AlertaSensor',      'ALERTA_SENSOR'],
  ['AlertaTemperatura', 'ALERTA_TEMPERATURA'],
  ['CercaAlvo',         'CERCA_ALVO'],
  ['CercaLogradouro',   'CERCA_LOGRADOURO'],
  ['CercaPoligonal',    'CERCA_POLIGONAL'],
  ['CercaRota',         'CERCA_ROTA'],
];

// BOOTSTRAP: quando o cursor enviado e 0 (primeira execucao, watermark zerado),
// a 3S NAO devolve eventos — devolve UM registro por dominio contendo so o id
// da ultima ocorrencia daquele dominio. E assim que se descobre o ponto de
// partida. Confirmado real em 04/08/2026, resposta com cursores em 0:
//   AlertaVelocidade: [{ idAlertaVelocidade: 156397661 }]
//   CercaLogradouro:  [{ idCercaLogradouro:  156397621 }]  ...
// Sem tratar isso o watermark ficaria preso em 0 para sempre e o fluxo nunca
// coletaria nada.
const CAMPOS_BOOTSTRAP = ['idAlertaVelocidade', 'idAlertaSensor', 'idAlertaTemperatura',
                          'idCercaAlvo', 'idCercaLogradouro', 'idCercaPoligonal', 'idCercaRota'];

let maxId = 0;
const itens = [];
const idsBootstrap = [];

for (const [chave, tipo] of TIPOS) {
  const records = dados[chave] || [];
  if (records.length === 0) continue;

  // Evento de verdade sempre traz idOcorrenciaAlerta; registro de bootstrap nao.
  const reais = records.filter(r => r && r.idOcorrenciaAlerta != null);

  if (reais.length === 0) {
    for (const r of records) {
      for (const campo of CAMPOS_BOOTSTRAP) {
        const v = parseInt(r && r[campo], 10);
        if (!isNaN(v) && v > 0) idsBootstrap.push(v);
      }
    }
    continue;
  }

  for (const rec of reais) {
    const idOc = parseInt(rec.idOcorrenciaAlerta, 10);
    if (!isNaN(idOc) && idOc > maxId) maxId = idOc;
  }
  itens.push({ json: { records: reais, tipo, rawId: id, maxId: 0 } }); // maxId preenchido abaixo
}

if (itens.length > 0) {
  // so agora maxId final e conhecido — preenche em todos os itens
  // (fn_avanca_watermark e monotonico/idempotente, repetir nao tem efeito)
  itens.forEach(it => it.json.maxId = maxId);
  return itens;
}

if (idsBootstrap.length > 0) {
  // MENOR id, nao o maior: reprocessar evento e idempotente (ON CONFLICT DO
  // NOTHING pela chave natural), mas perder evento nao tem volta.
  const cursorInicial = Math.min.apply(null, idsBootstrap);
  return [{ json: { records: [], tipo: 'BOOTSTRAP', rawId: id, maxId: cursorInicial, bootstrap: true } }];
}

// tipo como STRING (nao null): o parametro vai para options.queryReplacement
// do node Postgres seguinte, e um null dentro do array de parametros e um
// caminho que nao vale a pena exercitar. Com records vazio nada e inserido
// de qualquer forma, entao o valor aqui e so um rotulo.
return [{ json: { records: [], tipo: 'NENHUM', rawId: id, maxId: 0, vazio: true } }];
